import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() throws IOException {
            int c = in.read();
            while (isSpace(c)) {
                if (c == -1) throw new InputMismatchException();
                c = in.read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = in.read();
            }
            int res = 0;
            while (!isSpace(c)) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = in.read();
            }
            return res * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int k = fs.nextInt();

        int[] a = new int[n];
        int[] odd = new int[n];
        int balance = 0;
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
            balance += (a[i] & 1) == 0 ? 1 : -1;
            odd[i] = balance;
        }

        TreeMap<Integer, List<Integer>> groups = new TreeMap<>();
        for (int i = 0; i + 1 < n; i++) {
            int diff = Math.abs(a[i + 1] - a[i]);
            groups.computeIfAbsent(diff, x -> new ArrayList<>()).add(i);
        }

        int ans = 0;
        for (Map.Entry<Integer, List<Integer>> entry : groups.entrySet()) {
            int diff = entry.getKey();
            if (diff > k) break;

            List<Integer> indices = entry.getValue();
            Collections.sort(indices);

            for (int idx : indices) {
                if (k >= diff && odd[idx] == 0) {
                    int nk = k - diff;
                    if (nk >= 0) {
                        ans++;
                        k = nk;
                    }
                }
            }
        }
        System.out.println(ans);
    }
}
